batch=[]
for i,e in enumerate(L,1):
    b=body(e['team'],e['hook'],e['s'])
    wc=len(re.findall(r"\S+",b))
    slug=re.sub(r'[^a-z0-9]+','-',e['company'].lower()).strip('-')
    f=f"growth/outreach/queue-2026-11-02/{i:02d}-{slug}.md"
    open(os.path.join(OUT,f"{i:02d}-{slug}.md"),'w').write(f"# {e['company']}\n\nTo: {e['to']}\nSource: {e['source_url']}\nSubject: {e['subject']}\n\n{b}\n")
    batch.append(dict(company=e['company'],to=e['to'],source_url=e['source_url'],subject=e['subject'],body=b,slot=e['s'][0],
        in_directory=e['in_directory'],notes=e['oneliner'],route="email",send_on="2026-11-02",quote=e['quote'],
        numbers_check=e['numbers'],origin=e['origin'],word_count=wc,file=f))
    print(i,e['company'],wc)
json.dump(batch,open(os.path.join(OUT,'batch.json'),'w'),indent=1,ensure_ascii=False)
